"""fd_agent.py  --  the AskIT agent for the Front Desk, written to SEND EVENTS as it works.   >>> YOU DO NOT EDIT THIS FILE <<<

It is the same loop as Days 5 to 10:  ask the model -> it asks for a tool -> run the tool -> give the result back -> repeat.
The new part is `emit(...)`: every step is announced as a small event, so a web page can show it LIVE.

Events (what the browser receives):
  model_start  the AI model is being asked          model_end   it answered (time in ms)
  token        a piece of the answer text             tool_start  a tool is about to run
  tool_end     the tool finished (or failed)          final       the finished answer + numbers
  error        something went wrong

BREAK-IT SWITCHES (set in tab 3 of the page, passed in `chaos`):
  slow_tool    the ticket tool waits N seconds        tool_error   the ticket tool fails
  long_job     a 2-second pause between steps, so you can WATCH a long job
"""
import json
import sys
import time
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
for p in (str(ROOT), str(HERE)):
    if p not in sys.path:
        sys.path.insert(0, p)

from langchain_core.messages import HumanMessage, SystemMessage, ToolMessage   # noqa: E402
from langchain_core.tools import StructuredTool                                # noqa: E402

import model_factory as mf                                                     # noqa: E402
from askit_core import tools as T                                              # noqa: E402

PROMPT = ("You are AskIT, the Orbit Corp IT helpdesk assistant. Use the tools to answer. "
          "Answer in at most 3 short sentences. When you use a knowledge-base article, cite its id like [KB-004]. "
          "If the knowledge base has no article for the question, say so; do not guess.")
MAX_STEPS = 5


def make_tools():
    return [StructuredTool.from_function(func=lambda **kw: "", name=s["toolSpec"]["name"], description=s["toolSpec"]["description"],
                                         args_schema=s["toolSpec"]["inputSchema"]["json"]) for s in T.TOOL_SPECS]


def run_tool(name, args, chaos):
    """Run one tool. The break-it switches are applied here, in front of the real function."""
    if name == "get_ticket":
        if chaos.get("slow_tool"):
            time.sleep(float(chaos["slow_tool"]))
        if chaos.get("tool_error"):
            raise RuntimeError("Ticket database is down")
    fn = T.TOOLS.get(name)
    if fn is None:
        return {"error": f"No tool called {name}."}
    return fn(**args)


def _ms(t0):
    return int((time.time() - t0) * 1000)


def run(question, provider, chaos, emit, cancelled=lambda: False):
    """Answer one question and announce every step with emit(type, **data)."""
    t_start = time.time()
    pause = 2.0 if chaos.get("long_job") else 0.0
    tin = tout = 0
    try:
        model = mf.get_model(provider).bind_tools(make_tools())
        messages = [SystemMessage(content=PROMPT), HumanMessage(content=question)]
        answer = ""
        for step in range(1, MAX_STEPS + 1):
            if cancelled():
                emit("error", message="Stopped by you.")
                return
            if pause:
                time.sleep(pause)
            emit("model_start", n=step)
            t0 = time.time()
            if provider == "offline":                               # the stand-in cannot stream, so we play the answer out word by word
                msg = model.invoke(messages)
                text = mf.text_of(msg)
                for w in text.split(" "):
                    if w:
                        emit("token", step=step, text=w + " ")
                        time.sleep(0.09)
            else:                                                   # a real model streams pieces as it writes
                msg = None
                for chunk in model.stream(messages):
                    piece = mf.text_of(chunk)
                    if piece:
                        emit("token", step=step, text=piece)
                    msg = chunk if msg is None else msg + chunk
                text = mf.text_of(msg)
            um = getattr(msg, "usage_metadata", None) or {}
            tin += int(um.get("input_tokens") or mf.approx_tokens("".join(mf.text_of(m) for m in messages)))
            tout += int(um.get("output_tokens") or mf.approx_tokens(text or "tool call"))
            emit("model_end", n=step, ms=_ms(t0))
            answer = text
            messages.append(msg)
            if not msg.tool_calls:
                break
            for c in msg.tool_calls:
                if cancelled():
                    emit("error", message="Stopped by you.")
                    return
                if pause:
                    time.sleep(pause)
                emit("tool_start", name=c["name"], args=c["args"])
                t1 = time.time()
                try:
                    result, ok = run_tool(c["name"], c["args"], chaos), True
                except Exception as e:                              # noqa: BLE001
                    result, ok = {"error": f"{type(e).__name__}: {e}"}, False
                body = json.dumps(result, ensure_ascii=False)
                emit("tool_end", name=c["name"], ms=_ms(t1), ok=ok, preview=body[:160])
                messages.append(ToolMessage(content=body, tool_call_id=c["id"], name=c["name"]))
        else:
            answer = "(stopped: AskIT used all %d steps without a final answer)" % MAX_STEPS
        emit("final", answer=answer, ms=_ms(t_start), tokens_in=tin, tokens_out=tout,
             cost_usd=round(mf.cost_usd(provider, tin, tout), 6))
    except Exception as e:                                          # noqa: BLE001
        emit("error", message=f"{type(e).__name__}: {str(e)[:200]}")
